static void print_config(const anim_config_t *config)
{
    syslog(LOG_INFO, "config[curve:%d,p1:%f,p2:%f,p3:%f,p4:%f,direction_type:%d,iteration_count:%d\
        duration:%" PRIi32 ",delay:%" PRIi32 ",ratio:%f]",
        config->curve.curve_type, config->curve.p1, config->curve.p2,
        config->curve.p3, config->curve.p4, config->direction_type, config->iteration_count,
        config->duration, config->delay, config->ratio);
}

int anim_start_display_img(anim_config_t *config_test, const anim_value_t *val_test, anim_property_type_t property_type_test, anim_state_type_t state_test)
{
    int ret = 0;
    anim_id = anim_sequence_create(img_anim_handle);
    syslog(LOG_DEBUG, "anim_create_ret == %lld", anim_id);
    anim_config_set(img_anim_handle, anim_id, config_test);
    anim_config_get(img_anim_handle, anim_id, config_test);
    print_config(config_test);

    anim_property_add(img_anim_handle, anim_id, property_type_test, state_test, val_test);
    anim_property_config_set(img_anim_handle, anim_id, property_type_test, config_test);
    anim_property_config_get(img_anim_handle, anim_id, property_type_test, config_test);

    ui_imgtest = lv_image_create(ui_screen);
    lv_image_set_src(ui_imgtest, "/data/12.bin");
    lv_obj_set_x(ui_imgtest, 250);
    lv_obj_set_y(ui_imgtest, 250);
    lv_obj_set_width(ui_imgtest, 58);
    lv_obj_set_height(ui_imgtest, 58);
    ret = anim_start(img_anim_handle, anim_id, ui_imgtest, ANIM_LT_IMAGE);
    if (ret == 0)
    {
        return PASSED;
    }
    else
    {
        flag = 1;
        return FAILED;
    }
}

int anim__ANIM_CT_LINEAR__ANIM_PT_TRANSLATE_X__ANIM_ST_FROM__ANIM_DT_REVERSE_img(void)
{
    anim_config_t config;
    anim_property_type_t property_type_test;
    anim_state_type_t anim_state_type_test;
    memset(&config, 0, sizeof(anim_config_t));
    anim_config_set(img_anim_handle, anim_id, &config);
    anim_config_get(img_anim_handle, anim_id, &config);

    config.curve.curve_type = ANIM_CT_LINEAR;
    config.direction_type = ANIM_DT_REVERSE;
    config.duration = 2541;
    config.delay = 794;
    config.ratio = 1.5;
    config.iteration_count = 2;
    property_type_test = ANIM_PT_TRANSLATE_X;
    anim_state_type_test = ANIM_ST_FROM;
    anim_value_t val;
    val.type = ANIM_VT_FLOAT;
    val.v.fv = 167.2;

    if (anim_start_display_img(&config, &val, property_type_test, anim_state_type_test) == PASSED)
    {
        syslog(LOG_INFO, "[PASSED]  anim__ANIM_CT_LINEAR__ANIM_PT_TRANSLATE_X__ANIM_ST_FROM__ANIM_DT_REVERSE()");
        return PASSED;
    }
    else
    {
        flag = 1;
        syslog(LOG_INFO, "[FAILED]  anim__ANIM_CT_LINEAR__ANIM_PT_TRANSLATE_X__ANIM_ST_FROM__ANIM_DT_REVERSE()");
        return FAILED;
    }
}

